<script setup lang="ts">
import AppForm from './AppForm.vue';
import FormInput from './FormInput.vue';
import FormSelect from './FormSelect.vue';
import FormTextarea from './FormTextarea.vue';
import { notify, useFeedback } from '../services/feedback';
import { onMounted, ref } from 'vue';
import { api } from '../services/api';
import type { Badge, MunicipalSettings } from '../types';
import { municipalSettings } from '../services/municipalSettings';
import ConfirmDialog from './ConfirmDialog.vue';
import DashboardAppearance from './DashboardAppearance.vue';
import DepartmentManager from './DepartmentManager.vue';
const emit = defineEmits<{ changed: [] }>();
const settings = ref<MunicipalSettings>({ map: { latitude: 14.5995, longitude: 120.9842, zoom: 13 }, hotlines: [] });
const badges = ref<Badge[]>([]); const error = ref(''); const saved = ref(''); const busy = ref(false); const pending = ref<'settings' | number | null>(null);
const loading = ref(true); const ready = ref(false);
useFeedback([error], [saved]);
async function load() {
  loading.value = true; error.value = '';
  try {
    const [nextSettings, nextBadges] = await Promise.all([api<MunicipalSettings>('/api/settings'), api<Badge[]>('/api/badges')]);
    settings.value = nextSettings; badges.value = nextBadges; ready.value = true;
  } catch (e) { error.value = (e as Error).message; }
  finally { loading.value = false; }
}
onMounted(load);
async function save() { if (busy.value) return; saved.value = ''; busy.value = true; error.value = ''; try { if (pending.value === 'settings') { settings.value = await api<MunicipalSettings>('/api/admin/settings', { method: 'PUT', body: JSON.stringify(settings.value) }); municipalSettings.value = settings.value; saved.value = 'Map and hotlines saved.'; } else if (typeof pending.value === 'number') { const badge = badges.value.find(b => b.id === pending.value)!; const updated = await api<Badge>(`/api/admin/badges/${badge.id}`, { method: 'PATCH', body: JSON.stringify(badge) }); badges.value = badges.value.map(b => b.id === updated.id ? updated : b); saved.value = `${updated.name} badge saved.`; } pending.value = null; } catch (e) { error.value = (e as Error).message; } finally { busy.value = false; } }
</script>
<template><p v-if="loading" role="status">Loading municipal settings...</p><div v-else-if="ready" class="cms-grid"><DepartmentManager @changed="emit('changed')" /><DashboardAppearance /><section class="cms-card"><h2>Municipal map & emergency hotlines</h2><p class="field-help">The map opens at this location when no report is selected. Publish approved emergency numbers only.</p><AppForm class="form-body" @submit.prevent="pending = 'settings'"><div class="form-grid"><label>Default latitude<FormInput v-model.number="settings.map.latitude" type="number" step="any" min="-90" max="90" required name="settings.map.latitude" /></label><label>Default longitude<FormInput v-model.number="settings.map.longitude" type="number" step="any" min="-180" max="180" required name="settings.map.longitude" /></label></div><label>Default zoom<FormInput v-model.number="settings.map.zoom" type="number" step="any" min="3" max="19" required name="settings.map.zoom" /></label><h3>Emergency hotlines</h3><div v-for="(line, index) in settings.hotlines" :key="index" class="hotline-edit"><label>Service<FormInput v-model="line.name" required minlength="2" maxlength="80" placeholder="Municipal disaster office" name="line.name" /></label><label>Agency type<FormSelect v-model="line.service" name="line.service"><option value="other">Other</option><option value="police">Police</option><option value="fire">Fire</option><option value="medical">Medical</option><option value="rescue">Rescue / disaster response</option></FormSelect></label><label>Service area (optional)<FormInput v-model="line.area" maxlength="80" placeholder="Town or barangay served" name="line.area" /></label><label>Agency address (optional)<FormInput v-model="line.address" maxlength="160" name="line.address" /></label><label>Agency latitude (optional)<FormInput v-model.number="line.latitude" type="number" step="any" min="-90" max="90" name="line.latitude" /></label><label>Agency longitude (optional)<FormInput v-model.number="line.longitude" type="number" step="any" min="-180" max="180" name="line.longitude" /></label><label>Phone number<FormInput v-model="line.number" required maxlength="30" pattern="[+0-9\(\) \-]+" placeholder="Phone number" name="line.number" /></label><button class="text-button" type="button" @click="settings.hotlines.splice(index, 1); notify('Hotline removed from the draft. Save to publish your changes.', 'info')">Remove</button></div><button class="button secondary" type="button" :disabled="settings.hotlines.length >= 20" @click="settings.hotlines.push({ name: '', number: '' }); notify('Hotline row added. Enter the service and phone number.', 'info')">Add hotline</button><button class="button primary" type="submit">Save map and hotlines</button></AppForm></section>
<section class="cms-card"><h2>Achievement badges & rewards</h2><p class="field-help">Milestones use verified reports. Cash and gifts shown here are informational; fulfillment is handled by the municipality.</p><div v-for="badge in badges" :key="badge.id" class="badge-editor form-body"><span class="achievement-badge" :class="badge.color">{{ badge.name }} · {{ badge.threshold.toLocaleString() }}</span><label>Badge name<FormInput v-model="badge.name" maxlength="80" required name="badge.name" /></label><label>Description<FormTextarea v-model="badge.description" maxlength="1000" rows="2" required name="badge.description"></FormTextarea></label><label>Reward<FormSelect v-model="badge.reward_type" name="badge.reward_type"><option value="none">No reward</option><option value="cash">Cash bonus</option><option value="gift">Gift</option></FormSelect></label><label v-if="badge.reward_type === 'cash'">Cash amount (PHP)<FormInput v-model.number="badge.cash_amount" type="number" min="0" max="1000000" step="0.01" required name="badge.cash_amount" /></label><label v-if="badge.reward_type === 'gift'">Gift description<FormInput v-model="badge.reward_description" maxlength="255" required name="badge.reward_description" /></label><button class="button secondary" @click="pending = badge.id">Save {{ badge.name }}</button></div></section></div><button v-if="!ready && !loading" class="button secondary" @click="load">Retry loading settings</button><ConfirmDialog v-if="pending !== null" title="Publish CMS changes?" message="These changes will be visible in the citizen app immediately." :busy="busy" :error="error" confirm-label="Publish changes" @close="pending = null" @confirm="save" /></template>
